local k = 0
local function run(e)
	local m = #s
	local x0, y0, z0 = e.x, e.y, e.z
	Player:changPlayerMoveType(e.eventobjid, 1)
	Game:msgBox("正在生成请耐心等待！")
	for k = m, 1, -1 do
		Block:setBlockAll(x0 + s[k][1], y0 + s[k][2], z0 + s[k][3], s[k][4], s[k][5])
		Player:setPosition(e.eventobjid, x0 + s[k][1], y0 + s[k][2] + 5, z0 + s[k][3])
		if (m - k + 1) % 2000 == 0 then
			threadpool:wait(5)
			Game:msgBox("当前生成进度:" .. (math.floor((m - k + 1) * 10000 / m) / 100) .. "%")
		end
	end
	Game:msgBox("生成完成 -团梦秋提供技术支持")
	Player:changPlayerMoveType(e.eventobjid, 2)
end
ScriptSupportEvent:registerEvent("Block.PlaceBy", run)
